222	void ProviderAgent::begin_transcript(const AgentRequest& request)
223	{
224	    m_transcript = TurnTranscript{};
225	    m_transcript.request_id   = request.request_id;
226	    m_transcript.chat_key     = request.chat_key;
227	    m_transcript.instructions = request.session.instructions;
228	    m_on_recorded             = request.on_recorded;
229	    m_keep_blob               = request.keep_blob;
230	    m_unkept                  = false;
231	    std::vector<RecordItem>& items = m_transcript.items;
232	    const auto text = [](std::string value) {
233	        RecordPart part;
234	        part.text = std::move(value);
235	        return part;
236	    };
237	    if (request.purpose == AgentRequest::Purpose::ConversationTitle) {
238	        items.push_back(RecordItem{RecordItem::Kind::User, {}, {text(request.user_text)}});
239	        m_recorded = m_settled = items.size();
240	        return;
241	    }
242	    if (!m_on_recorded || !m_keep_blob)
243	        throw std::logic_error("a reply request with nowhere to keep what it sends");
244	    items      = request.record.items;
245	    m_recorded = items.size();
246	    m_transcript.tools = offered_tools(request);
247	
248	    // What the model has not been sent yet, the person's side first: a
249	    // message that never reached it, then this turn's own.
250	    for (const RecordItem& item : request.unsent)
251	        if (item.kind == RecordItem::Kind::User)
252	            items.push_back(item);
253	    // Kept from here once the provider accepts the request: the person's side.
254	    m_settled = items.size();
255	    // One part per kind of content: the person's words exactly as typed, then
256	    // the app's data, each in its own tag, then the attachments. A turn the
257	    // app started on its note has only the data, kept with the note once the
258	    // model has answered both; a retry whose turn the record already holds
259	    // adds nothing.
260	    const bool app_turn = !request.note.empty();
261	    RecordItem turn{RecordItem::Kind::User, app_turn ? std::string() : request.source, {}};
262	    if (!request.user_text.empty())
263	        turn.parts.push_back(text(request.user_text));
264	    if (!request.issue_context.empty())
265	        turn.parts.push_back(text(tagged_block("print_issue", request.issue_context)));
266	    if (!request.turn_recorded && request.session.include_workspace)
267	        turn.parts.push_back(text(tagged_block("workspace", workspace_json(request).dump())));
268	    std::ostringstream attachments;
269	    for (const auto& attachment : request.attachments) {
270	        if (attachments.tellp() > 0)
271	            attachments << "\n";
272	        attachments << "Attachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
273	        if (!attachment.summary.empty())
274	            attachments << " — " << attachment.summary;
275	        if (!attachment.text.empty())
276	            attachments << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
277	    }
278	    if (attachments.tellp() > 0)
279	        turn.parts.push_back(text(attachments.str()));
280	    for (const auto& attachment : request.attachments) {
281	        if (attachment.bytes.empty() || (attachment.kind != "image" && attachment.kind != "pdf"))
282	            continue;
283	        RecordPart part;
284	        part.kind   = attachment.kind == "image" ? RecordPart::Kind::Image : RecordPart::Kind::Pdf;
285	        part.mime   = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
286	        part.base64 = base64_encode(attachment.bytes);
287	        if (part.kind == RecordPart::Kind::Pdf)
288	            part.filename = attachment.name;
289	        turn.parts.push_back(kept(std::move(part)));
290	    }
291	    if (!turn.parts.empty())
292	        items.push_back(std::move(turn));
293	    // What the app adds from here is kept once the model has answered it:
294	    // its notes, the turn's own last, in the operator's voice.
295	    if (!app_turn)
296	        m_settled = items.size();
297	    std::vector<RecordItem> notes;
298	    for (const RecordItem& item : request.unsent)
299	        if (item.kind == RecordItem::Kind::Operator)
300	            notes.push_back(item);
301	    if (app_turn)
302	        notes.push_back(RecordItem{RecordItem::Kind::Operator, request.source, {}, request.note});
303	    push_skills(skills_to_send(request.skills), std::move(notes));
304	}
