306	void ProviderAgent::push_skills(const std::vector<AgentSkillUse>& skills, std::vector<RecordItem> notes)
307	{
308	    // Each fired skill's picture on the person's side, then the app's voice:
309	    // its notes, then every skill's text, for this request only where the
310	    // provider can clear it.
311	    for (const AgentSkillUse& skill : skills)
312	        if (skill.picture)
313	            m_transcript.items.push_back(RecordItem{RecordItem::Kind::User, {}, {kept(image_part(*skill.picture))}});
314	    for (RecordItem& note : notes)
315	        m_transcript.items.push_back(std::move(note));
316	    for (const AgentSkillUse& skill : skills)
317	        m_transcript.items.push_back(RecordItem{RecordItem::Kind::Operator, {}, {}, skill.text, {}, {}, true});
318	}
