320	RecordPart ProviderAgent::kept(RecordPart part)
321	{
322	    if (const std::optional<std::string> blob = m_keep_blob(part.base64))
323	        part.blob = *blob;
324	    else
325	        m_unkept = true;
326	    return part;
327	}
