329	void ProviderAgent::record()
330	{
331	    // A title request belongs to no chat: nothing it sends or gets is kept.
332	    if (m_kind == RequestKind::ConversationTitle || m_settled <= m_recorded)
333	        return;
334	    m_on_recorded(wire_format(m_config.profile.family),
335	                  std::vector<RecordItem>(m_transcript.items.begin() + m_recorded, m_transcript.items.begin() + m_settled));
336	    m_recorded = m_settled;
337	}
