339	bool ProviderAgent::start(const AgentRequest& request)
340	{
341	    if (!ready() || m_busy)
342	        return false;
343	    m_pending_call_id.clear();
344	    m_pending_tool.clear();
345	    m_queued_calls.clear();
346	    m_step_skills.clear();
347	    m_results = RecordItem{RecordItem::Kind::Results};
348	    m_failed_call.clear();
349	    m_waiting_for_tool = false;
350	    m_rejected_calls   = 0;
351	    m_paused_turns     = 0;
352	    m_kind = request.purpose == AgentRequest::Purpose::ConversationTitle ? RequestKind::ConversationTitle : RequestKind::Reply;
353	    begin_transcript(request);
354	    return post();
355	}
