357	bool ProviderAgent::continue_after_tool(const AgentToolResult& result)
358	{
359	    if (!m_busy || !m_waiting_for_tool || result.call_id != m_pending_call_id)
360	        return false;
361	    m_results.results.push_back(RecordResult{result.call_id, result.output_json, result.state != "succeeded",
362	                                             result.image ? std::optional<RecordPart>(kept(image_part(*result.image))) : std::nullopt});
363	    for (const AgentSkillUse& skill : result.skills) {
364	        const auto same = std::find_if(m_step_skills.begin(), m_step_skills.end(),
365	                                       [&skill](const AgentSkillUse& pending) { return pending.name == skill.name; });
366	        if (same != m_step_skills.end())
367	            *same = skill;
368	        else
369	            m_step_skills.push_back(skill);
370	    }
371	    if (result.state != "succeeded" && m_failed_call.empty())
372	        m_failed_call = m_pending_tool + " (" + m_pending_call_id + ")";
373	    m_waiting_for_tool = false;
374	    m_pending_call_id.clear();
375	    m_pending_tool.clear();
376	    return next_call();
377	}
