384	bool ProviderAgent::post()
385	{
386	    // A picture the record could not keep: the chat could never send this
387	    // request again, so it is not sent now.
388	    if (m_unkept) {
389	        m_busy = false;
390	        return false;
391	    }
392	    m_sse_buffer.clear();
393	    m_terminal_seen = false;
394	    m_busy = true;
395	    ++m_transcript.request_sequence;
396	    m_codec->reset();
397	    ProviderRequest built = m_codec->build(m_transcript, m_config.profile, m_kind);
398	    AgentHttpRequest request;
399	    request.url = m_config.profile.endpoint;
400	    request.headers.push_back(auth_header(m_config.profile, m_config.api_key));
401	    request.headers.insert(request.headers.end(), m_config.profile.headers.begin(), m_config.profile.headers.end());
402	    request.headers.insert(request.headers.end(), built.headers.begin(), built.headers.end());
403	    if (m_config.profile.account_sign_in) {
404	        request.headers.push_back({"X-JusPrin-Turn", m_transcript.request_id});
405	        request.headers.push_back({"X-JusPrin-Request", m_kind == RequestKind::ConversationTitle ? "title" : "reply"});
406	        // The gateway keeps each chat whole, named by this. A copied project
407	        // gets a new project id, so its chats get new names too.
408	        if (!m_transcript.chat_key.empty())
409	            request.headers.push_back({"X-JusPrin-Chat", sha256_hex(m_transcript.chat_key).substr(0, 32)});
410	    }
411	    request.body = built.body.dump();
412	    const std::uint64_t generation = ++m_http_generation;
413	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
414	            accept_http(generation, std::move(event));
415	        })) {
416	        m_busy = false;
417	        return false;
418	    }
419	    return true;
420	}
