24	namespace Slic3r::GUI::JusPrin::Agent {
25	
26	class RequestLog
27	{
28	public:
29	    // Chat ids restart in each project, so a chat is named by both.
30	    struct Chat
31	    {
32	        std::string project_id;
33	        std::string chat_id;
34	    };
35	
36	    // `directory` must be new or empty, so a run's numbering never mixes with
37	    // an earlier run's. `chat` is read at each post.
38	    RequestLog(std::filesystem::path directory, std::function<Chat()> chat)
39	        : m_state(std::make_shared<State>(State{std::move(directory), std::move(chat), 0}))
40	    {
41	        std::filesystem::create_directories(m_state->directory);
42	        if (!std::filesystem::is_empty(m_state->directory))
43	            throw std::runtime_error("the request log directory is not empty: " + m_state->directory.string());
44	    }
45	
46	    std::unique_ptr<IAgentHttpTransport> transport(std::unique_ptr<IAgentHttpTransport> inner) const
47	    {
48	        return std::make_unique<Transport>(m_state, std::move(inner));
49	    }
50	
51	private:
52	    struct State
53	    {
54	        std::filesystem::path directory;
55	        std::function<Chat()> chat;
56	        int                   count;
57	    };
58	
59	    class Transport final : public IAgentHttpTransport
60	    {
61	    public:
62	        Transport(std::shared_ptr<State> state, std::unique_ptr<IAgentHttpTransport> inner) : m_state(std::move(state)), m_inner(std::move(inner)) {}
63	
64	        bool post(AgentHttpRequest request, EventFn event) override
65	        {
66	            char stem[8];
67	            std::snprintf(stem, sizeof stem, "%04d", ++m_state->count);
68	            std::ofstream(m_state->directory / (std::string(stem) + "-request.json"), std::ios::binary) << request.body;
69	            const Chat chat  = m_state->chat();
70	            auto       usage = std::make_shared<std::ofstream>(m_state->directory / (std::string(stem) + "-usage.txt"), std::ios::binary);
71	            *usage << chat.project_id << ' ' << chat.chat_id << '\n' << std::flush;
72	            auto pending = std::make_shared<std::string>(); // a stream line split across chunks
73	            return m_inner->post(std::move(request), [usage, pending, event = std::move(event)](AgentHttpEvent received) {
74	                if (received.kind == AgentHttpEvent::Kind::Data) {
75	                    *pending += received.data;
76	                    for (std::size_t end; (end = pending->find('\n')) != std::string::npos; pending->erase(0, end + 1)) {
77	                        if (pending->compare(0, 5, "data:") != 0)
78	                            continue;
79	                        const nlohmann::json line = nlohmann::json::parse(pending->substr(5, end - 5), nullptr, false);
80	                        // Anthropic: message_start's message.usage and message_delta's usage; Responses: response.usage.
81	                        for (const char* at : {"/usage", "/message/usage", "/response/usage"}) {
82	                            const nlohmann::json::json_pointer pointer(at);
83	                            if (line.is_object() && line.contains(pointer) && line.at(pointer).is_object())
84	                                *usage << line.at(pointer).dump() << '\n' << std::flush;
85	                        }
86	                    }
87	                }
88	                event(std::move(received));
89	            });
90	        }
91	
92	        void cancel() override { m_inner->cancel(); }
93	
94	    private:
95	        std::shared_ptr<State>               m_state;
96	        std::unique_ptr<IAgentHttpTransport> m_inner;
97	    };
98	
99	    std::shared_ptr<State> m_state;
100	};
