55	AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
56	                                   const std::string&                                           endpoint_override,
57	                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
58	                                   ProviderListeners                                            listeners)
59	{
60	    AgentRuntime runtime;
61	    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
62	    if (!settings.enabled) {
63	        runtime.unavailable_reason = "The Agent is not enabled.";
64	        return runtime;
65	    }
66	    const ProviderProfile* profile = profile_for(runtime.provider);
67	    if (profile == nullptr) {
68	        runtime.unavailable_reason = "The configured Agent provider is not supported.";
69	        return runtime;
70	    }
71	    if (!settings.cloud_consent) {
72	        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
73	        return runtime;
74	    }
75	    if (settings.api_key.empty()) {
76	        runtime.unavailable_reason = profile->account_sign_in ? "Not signed in to a JusPrin account." :
77	                                                                "No " + profile->display_name + " API key is configured.";
78	        return runtime;
79	    }
80	    if (profile->account_sign_in) {
81	        const std::optional<ProviderProfile> served =
82	            account_profile(*profile, endpoint_override.empty() ? settings.endpoint : endpoint_override, settings.format);
83	        if (!served) {
84	            runtime.unavailable_reason = "Sign in to your JusPrin account again.";
85	            return runtime;
86	        }
87	        runtime.service = make_provider_agent(*served, settings.api_key, settings.model, {}, transport(), std::move(listeners));
88	    } else {
89	        runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
90	                                              std::move(listeners));
91	    }
92	    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
93	    if (runtime.availability == AgentAvailability::Unavailable)
94	        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
95	    return runtime;
96	}
