#!/usr/bin/env python3
"""Real app, fake provider: sends one chat message through the app's own agent
and compares what the provider received with the request log file. No model."""
import http.server, json, os, pathlib, shutil, subprocess, sys, threading, time

S = pathlib.Path(__file__).resolve().parent
ROOT = pathlib.Path('/Users/kenneth/Projects/JusPrin')
HARNESS = ROOT / 'build/arm64/tests/shell/RelWithDebInfo/JusPrinShellHarness.app/Contents/MacOS/JusPrinShellHarness'
FIXTURE = S / 'reqlog-fixture'
HOME = S / 'reqlog-home'
KEY = 'sk-TESTONLY-request-log-check'
PORT = 47911

for d in (FIXTURE, HOME):
    shutil.rmtree(d, ignore_errors=True)
    d.mkdir(parents=True)
(FIXTURE / 'JusPrin2.conf').write_text(json.dumps({'app': {}, 'jusprin_agent': {
    'enabled': 'true', 'cloud_consent': 'true', 'provider': 'openai', 'openai_api_key': KEY}}))

INJECT = """<script>
(function () {
  const log = (m) => fetch('/log?' + encodeURIComponent(m)).catch(() => {});
  const send = () => {
    if (!window.wx) { setTimeout(send, 500); return; }
    log('sending');
    window.wx.postMessage(JSON.stringify({protocol: 'jusprin-agent-bridge', version: 1, id: 'check-1',
      type: 'user_message', payload: {text: 'request log check', attachmentIds: [], clientMessageId: 'check-client-1'}}));
  };
  setTimeout(send, 12000);
})();
</script>"""
page = (S / 'agent-bundle/index.html').read_text()
page = page.replace('<head>', '<head>' + INJECT, 1)
assert INJECT in page

received = []
class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        if self.path.startswith('/log?'):
            print('PAGE', self.path[5:], flush=True)
        body = page.encode() if self.path.startswith('/page.html') else b'{"data":[]}'
        self.send_response(200); self.send_header('Content-Length', str(len(body))); self.end_headers(); self.wfile.write(body)
    def do_POST(self):
        body = self.rfile.read(int(self.headers.get('Content-Length', 0)))
        received.append((self.headers.get('Authorization', ''), body))
        out = b'{"error":{"message":"fake provider","type":"server_error"}}'
        self.send_response(500); self.send_header('Content-Length', str(len(out))); self.end_headers(); self.wfile.write(out)

server = http.server.ThreadingHTTPServer(('127.0.0.1', PORT), Handler)
threading.Thread(target=server.serve_forever, daemon=True).start()

env = dict(os.environ, HOME=str(HOME),
           JUSPRIN_AGENT_DEV_URL=f'http://127.0.0.1:{PORT}/page.html',
           JUSPRIN_AGENT_ENDPOINT=f'http://127.0.0.1:{PORT}/v1/responses')
err = open(S / 'reqlog-harness.log', 'w')
proc = subprocess.Popen([str(HARNESS), '--manual-mcp', str(FIXTURE)], env=env, stdout=err, stderr=err)
log_dir = FIXTURE / 'jusprin/request-log'
failed = []
try:
    deadline = time.time() + 150
    while time.time() < deadline and not received and proc.poll() is None:
        time.sleep(1)
    time.sleep(3)
    print('provider received', len(received), 'requests; harness exit', proc.poll())
    files = sorted(log_dir.glob('*.json')) if log_dir.exists() else []
    print('log files', [f.name for f in files], 'in', log_dir)
    if not received: failed.append('no request reached the fake provider')
    if not files: failed.append('no log file')
    if received and files:
        auth, wire = received[0]
        print('Authorization carried the key:', auth == 'Bearer ' + KEY)
        logged = json.loads(files[0].read_text())
        print('fields', {k: logged[k] for k in ('provider', 'chat', 'turn', 'sequence')})
        print('body keys', sorted(logged['body']), 'file bytes', files[0].stat().st_size, 'wire bytes', len(wire))
        if json.loads(wire) != logged['body']: failed.append('logged body differs from the wire')
        else: print('logged body equals the body the provider received')
        if 'request log check' not in json.dumps(logged['body']): failed.append('the message is not in the log')
        if KEY in files[0].read_text(): failed.append('the key is in the log')
        else: print('the key is not in the log file')
finally:
    proc.terminate()
    try: proc.wait(30)
    except subprocess.TimeoutExpired: proc.kill()
    server.shutdown()
print('RESULT', 'FAIL ' + '; '.join(failed) if failed else 'PASS')
sys.exit(1 if failed else 0)

